-- Migration 000: base schema (the state of the database BEFORE migration 001).
--
-- Rebuilds, on an empty Supabase project, the tables, constraints, RLS and
-- policies that were originally created by hand in the SQL Editor. Run it
-- first, then 001..010 in order. It was generated by reading the live catalog
-- (pg_attribute, pg_constraint, pg_policies, storage.buckets) of the project,
-- and it deliberately leaves out everything that later migrations add:
--   - posts.likes_count / comments_count, profiles.followers_count /
--     following_count                                  (006_counters)
--   - the notifications table and its policies          (007_notifications)
--   - policies messages_update_own, messages_delete_own, comments_update_own,
--     reviews_update_own, reviews_delete_own            (003_missing_policies)
--   - grants, column privileges, storage policies and bucket limits
--                                                       (009, 010)
--   - functions, triggers and indexes                   (001..008)
-- The policies below are created without a TO clause (role "public"), as they
-- were originally; migration 009 then moves them to authenticated.
--
-- messages.read_at already existed before 008 (it was added by hand), so it is
-- part of this base state; 008 adds it with IF NOT EXISTS and is a no-op here.
--
-- profiles.id references auth.users(id): profiles rows are created by the
-- client after sign-up (there is no trigger on auth.users).
--
-- Idempotent: IF NOT EXISTS on tables and buckets, DROP POLICY IF EXISTS before
-- each policy. One transaction: it applies fully or not at all.

BEGIN;

-- 1. Tables -----------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.profiles (
  id            uuid        NOT NULL,
  username      text,
  avatar_url    text,
  bio           text,
  created_at    timestamptz DEFAULT timezone('utc'::text, now()),
  setup_complete boolean    DEFAULT false,
  CONSTRAINT profiles_pkey PRIMARY KEY (id),
  CONSTRAINT profiles_username_key UNIQUE (username),
  CONSTRAINT profiles_id_fkey FOREIGN KEY (id)
    REFERENCES auth.users(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.posts (
  id            uuid        NOT NULL DEFAULT gen_random_uuid(),
  user_id       uuid,
  product       text        NOT NULL,
  brand         text,
  price         text,
  where_bought  text,
  caption       text,
  emoji         text        DEFAULT '🛍️',
  created_at    timestamptz DEFAULT timezone('utc'::text, now()),
  image_url     text,
  for_sale      boolean     DEFAULT false,
  sale_price    text,
  category      text,
  image_urls    text[]      DEFAULT '{}'::text[],
  CONSTRAINT posts_pkey PRIMARY KEY (id),
  CONSTRAINT posts_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.comments (
  id            uuid        NOT NULL DEFAULT gen_random_uuid(),
  post_id       uuid,
  user_id       uuid,
  content       text        NOT NULL,
  created_at    timestamptz DEFAULT timezone('utc'::text, now()),
  CONSTRAINT comments_pkey PRIMARY KEY (id),
  CONSTRAINT comments_post_id_fkey FOREIGN KEY (post_id)
    REFERENCES public.posts(id) ON DELETE CASCADE,
  CONSTRAINT comments_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.likes (
  id            uuid        NOT NULL DEFAULT gen_random_uuid(),
  post_id       uuid,
  user_id       uuid,
  created_at    timestamptz DEFAULT timezone('utc'::text, now()),
  CONSTRAINT likes_pkey PRIMARY KEY (id),
  CONSTRAINT likes_post_id_user_id_key UNIQUE (post_id, user_id),
  CONSTRAINT likes_post_id_fkey FOREIGN KEY (post_id)
    REFERENCES public.posts(id) ON DELETE CASCADE,
  CONSTRAINT likes_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.follows (
  id            uuid        NOT NULL DEFAULT gen_random_uuid(),
  follower_id   uuid,
  following_id  uuid,
  created_at    timestamptz DEFAULT timezone('utc'::text, now()),
  CONSTRAINT follows_pkey PRIMARY KEY (id),
  CONSTRAINT follows_follower_id_following_id_key UNIQUE (follower_id, following_id),
  CONSTRAINT follows_follower_id_fkey FOREIGN KEY (follower_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE,
  CONSTRAINT follows_following_id_fkey FOREIGN KEY (following_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.conversations (
  id            uuid        NOT NULL DEFAULT gen_random_uuid(),
  user1_id      uuid,
  user2_id      uuid,
  created_at    timestamptz DEFAULT timezone('utc'::text, now()),
  CONSTRAINT conversations_pkey PRIMARY KEY (id),
  CONSTRAINT conversations_user1_id_user2_id_key UNIQUE (user1_id, user2_id),
  CONSTRAINT conversations_user1_id_fkey FOREIGN KEY (user1_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE,
  CONSTRAINT conversations_user2_id_fkey FOREIGN KEY (user2_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.messages (
  id              uuid        NOT NULL DEFAULT gen_random_uuid(),
  conversation_id uuid,
  sender_id       uuid,
  content         text        NOT NULL,
  created_at      timestamptz DEFAULT timezone('utc'::text, now()),
  read_at         timestamptz,
  updated_at      timestamptz,
  CONSTRAINT messages_pkey PRIMARY KEY (id),
  CONSTRAINT messages_conversation_id_fkey FOREIGN KEY (conversation_id)
    REFERENCES public.conversations(id) ON DELETE CASCADE,
  CONSTRAINT messages_sender_id_fkey FOREIGN KEY (sender_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.reviews (
  id            uuid        NOT NULL DEFAULT gen_random_uuid(),
  post_id       uuid,
  user_id       uuid,
  rating        integer,
  content       text,
  recommended   boolean,
  created_at    timestamptz DEFAULT timezone('utc'::text, now()),
  CONSTRAINT reviews_pkey PRIMARY KEY (id),
  CONSTRAINT reviews_rating_check CHECK (((rating >= 1) AND (rating <= 5))),
  CONSTRAINT reviews_post_id_fkey FOREIGN KEY (post_id)
    REFERENCES public.posts(id) ON DELETE CASCADE,
  CONSTRAINT reviews_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.saves (
  id            bigint      GENERATED ALWAYS AS IDENTITY,
  post_id       uuid,
  user_id       uuid,
  created_at    timestamptz DEFAULT now(),
  CONSTRAINT saves_pkey PRIMARY KEY (id),
  CONSTRAINT saves_post_id_user_id_key UNIQUE (post_id, user_id),
  CONSTRAINT saves_post_id_fkey FOREIGN KEY (post_id)
    REFERENCES public.posts(id) ON DELETE CASCADE,
  CONSTRAINT saves_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.blocked_users (
  id            bigint      GENERATED ALWAYS AS IDENTITY,
  blocker_id    uuid,
  blocked_id    uuid,
  created_at    timestamptz DEFAULT now(),
  CONSTRAINT blocked_users_pkey PRIMARY KEY (id),
  CONSTRAINT blocked_users_blocker_id_blocked_id_key UNIQUE (blocker_id, blocked_id),
  CONSTRAINT blocked_users_blocked_id_fkey FOREIGN KEY (blocked_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE,
  CONSTRAINT blocked_users_blocker_id_fkey FOREIGN KEY (blocker_id)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.reports (
  id            bigint      GENERATED ALWAYS AS IDENTITY,
  post_id       uuid,
  reported_by   uuid,
  reason        text        NOT NULL,
  created_at    timestamptz DEFAULT now(),
  CONSTRAINT reports_pkey PRIMARY KEY (id),
  CONSTRAINT reports_post_id_fkey FOREIGN KEY (post_id)
    REFERENCES public.posts(id) ON DELETE CASCADE,
  CONSTRAINT reports_reported_by_fkey FOREIGN KEY (reported_by)
    REFERENCES public.profiles(id) ON DELETE CASCADE
);

-- 2. Row Level Security -----------------------------------------------------

ALTER TABLE public.profiles      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts         ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.likes         ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.follows       ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews       ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.saves         ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blocked_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reports       ENABLE ROW LEVEL SECURITY;

-- 3. Policies (the original ones; no TO clause = role "public") --------------

-- profiles
DROP POLICY IF EXISTS profiles_select ON public.profiles;
CREATE POLICY profiles_select ON public.profiles FOR SELECT USING (true);
DROP POLICY IF EXISTS profiles_insert ON public.profiles;
CREATE POLICY profiles_insert ON public.profiles FOR INSERT
  WITH CHECK (id = auth.uid());
DROP POLICY IF EXISTS profiles_update ON public.profiles;
CREATE POLICY profiles_update ON public.profiles FOR UPDATE
  USING (id = auth.uid()) WITH CHECK (id = auth.uid());

-- posts
DROP POLICY IF EXISTS "Posts visibles para todos" ON public.posts;
CREATE POLICY "Posts visibles para todos" ON public.posts FOR SELECT USING (true);
DROP POLICY IF EXISTS "Usuario crea sus propios posts" ON public.posts;
CREATE POLICY "Usuario crea sus propios posts" ON public.posts FOR INSERT
  WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "Usuario edita sus propios posts" ON public.posts;
CREATE POLICY "Usuario edita sus propios posts" ON public.posts FOR UPDATE
  USING (auth.uid() = user_id);
DROP POLICY IF EXISTS posts_delete ON public.posts;
CREATE POLICY posts_delete ON public.posts FOR DELETE
  USING (user_id = auth.uid());

-- comments
DROP POLICY IF EXISTS "Comentarios visibles para todos" ON public.comments;
CREATE POLICY "Comentarios visibles para todos" ON public.comments
  FOR SELECT USING (true);
DROP POLICY IF EXISTS "Usuario crea sus propios comentarios" ON public.comments;
CREATE POLICY "Usuario crea sus propios comentarios" ON public.comments
  FOR INSERT WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "Usuario borra sus propios comentarios" ON public.comments;
CREATE POLICY "Usuario borra sus propios comentarios" ON public.comments
  FOR DELETE USING (auth.uid() = user_id);

-- likes
DROP POLICY IF EXISTS "Likes visibles para todos" ON public.likes;
CREATE POLICY "Likes visibles para todos" ON public.likes FOR SELECT USING (true);
DROP POLICY IF EXISTS "Usuario crea sus propios likes" ON public.likes;
CREATE POLICY "Usuario crea sus propios likes" ON public.likes FOR INSERT
  WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "Usuario borra sus propios likes" ON public.likes;
CREATE POLICY "Usuario borra sus propios likes" ON public.likes FOR DELETE
  USING (auth.uid() = user_id);

-- follows
DROP POLICY IF EXISTS "Follows visibles para todos" ON public.follows;
CREATE POLICY "Follows visibles para todos" ON public.follows
  FOR SELECT USING (true);
DROP POLICY IF EXISTS "Usuario puede seguir" ON public.follows;
CREATE POLICY "Usuario puede seguir" ON public.follows FOR INSERT
  WITH CHECK (auth.uid() = follower_id);
DROP POLICY IF EXISTS "Usuario puede dejar de seguir" ON public.follows;
CREATE POLICY "Usuario puede dejar de seguir" ON public.follows FOR DELETE
  USING (auth.uid() = follower_id);

-- conversations
DROP POLICY IF EXISTS "Usuario ve sus conversaciones" ON public.conversations;
CREATE POLICY "Usuario ve sus conversaciones" ON public.conversations
  FOR SELECT USING ((auth.uid() = user1_id) OR (auth.uid() = user2_id));
DROP POLICY IF EXISTS "Usuario crea conversaciones" ON public.conversations;
CREATE POLICY "Usuario crea conversaciones" ON public.conversations
  FOR INSERT WITH CHECK ((auth.uid() = user1_id) OR (auth.uid() = user2_id));

-- messages
DROP POLICY IF EXISTS "Usuario ve mensajes de sus conversaciones" ON public.messages;
CREATE POLICY "Usuario ve mensajes de sus conversaciones" ON public.messages
  FOR SELECT USING (EXISTS (
    SELECT 1 FROM public.conversations
    WHERE conversations.id = messages.conversation_id
      AND (conversations.user1_id = auth.uid()
           OR conversations.user2_id = auth.uid())
  ));
DROP POLICY IF EXISTS "Usuario envia mensajes en sus conversaciones" ON public.messages;
CREATE POLICY "Usuario envia mensajes en sus conversaciones" ON public.messages
  FOR INSERT WITH CHECK (
    auth.uid() = sender_id
    AND EXISTS (
      SELECT 1 FROM public.conversations
      WHERE conversations.id = messages.conversation_id
        AND (conversations.user1_id = auth.uid()
             OR conversations.user2_id = auth.uid())
    )
  );

-- reviews
DROP POLICY IF EXISTS "Reviews visibles para todos" ON public.reviews;
CREATE POLICY "Reviews visibles para todos" ON public.reviews
  FOR SELECT USING (true);
DROP POLICY IF EXISTS "Usuario crea sus propias reviews" ON public.reviews;
CREATE POLICY "Usuario crea sus propias reviews" ON public.reviews
  FOR INSERT WITH CHECK (auth.uid() = user_id);

-- saves
DROP POLICY IF EXISTS saves_select ON public.saves;
CREATE POLICY saves_select ON public.saves FOR SELECT USING (user_id = auth.uid());
DROP POLICY IF EXISTS saves_insert ON public.saves;
CREATE POLICY saves_insert ON public.saves FOR INSERT
  WITH CHECK (user_id = auth.uid());
DROP POLICY IF EXISTS saves_delete ON public.saves;
CREATE POLICY saves_delete ON public.saves FOR DELETE USING (user_id = auth.uid());

-- blocked_users
DROP POLICY IF EXISTS blocked_users_select ON public.blocked_users;
CREATE POLICY blocked_users_select ON public.blocked_users
  FOR SELECT USING (blocker_id = auth.uid());
DROP POLICY IF EXISTS blocked_users_insert ON public.blocked_users;
CREATE POLICY blocked_users_insert ON public.blocked_users
  FOR INSERT WITH CHECK (blocker_id = auth.uid());
DROP POLICY IF EXISTS blocked_users_delete ON public.blocked_users;
CREATE POLICY blocked_users_delete ON public.blocked_users
  FOR DELETE USING (blocker_id = auth.uid());

-- reports (write-only for users: nobody reads them from the client)
DROP POLICY IF EXISTS reports_insert ON public.reports;
CREATE POLICY reports_insert ON public.reports FOR INSERT
  WITH CHECK (reported_by = auth.uid());

-- 4. Storage buckets --------------------------------------------------------
-- Created public (images are shown by URL). Size limits, allowed types and the
-- policies of storage.objects are set by migration 010.
INSERT INTO storage.buckets (id, name, public)
VALUES ('avatars', 'avatars', true),
       ('posts',   'posts',   true),
       ('chat',    'chat',    true)
ON CONFLICT (id) DO NOTHING;

COMMIT;

-- Check (run after the COMMIT): 11 tables, all with RLS on.
--   SELECT count(*) AS tables, count(*) FILTER (WHERE relrowsecurity) AS with_rls
--   FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
--   WHERE n.nspname = 'public' AND c.relkind = 'r';
